        final label = picked.substring(6);
        final slash = label.indexOf('/');
        await _editModelCapsOverride(
          label.substring(0, slash),
          label.substring(slash + 1),
        );
      }
    }
  }

  /// The one-line summary of a pinned override (menu descriptions).
