/// Edits [text] so the dotted [segments] path is REMOVED, keeping every
/// unrelated line byte-identical:
///
/// - the leaf key line and its block body are deleted;
/// - an ancestor whose block becomes empty is deleted too (a removed last
///   leaf under `models.overrides.zai.glm` drops the emptied `glm:` /
///   `zai:` blocks up the chain);
/// - a missing path is a no-op.
///
/// Same line-scan rules as [upsertYamlPath] (the CRAP ratchet split those
/// helpers out; this one shares them).
String removeYamlPath(String text, List<String> segments) {
  if (segments.isEmpty) return text;
  final hadTrailingNewline = text.endsWith('\n');
  final lines = text.isEmpty
      ? <String>[]
      : (hadTrailingNewline ? text.substring(0, text.length - 1) : text).split(
          '\n',
        );
  final foundAt = <int>[];
  var cursor = 0;
  for (var depth = 0; depth < segments.length; depth++) {
    final found = _findKeyLine(lines, segments, depth, cursor);
    if (found < 0) return text; // absent path — nothing to remove
    foundAt.add(found);
    cursor = found + 1;
  }
  // Delete deepest-first: the leaf's block body, then emptied ancestors.
  for (var depth = segments.length - 1; depth >= 0; depth--) {
    final keyLine = foundAt[depth];
    final end = _blockEnd(lines, keyLine, depth);
    lines.removeRange(keyLine, end);
    // An emptied ancestor block: the parent key line now carries no body.
    if (depth > 0) {
      final parentLine = foundAt[depth - 1];
      if (_blockEnd(lines, parentLine, depth - 1) == parentLine + 1) {
        continue; // loop's next iteration removes the emptied parent
      }
      break;
    }
  }
  return _join(lines, hadTrailingNewline);
}

/// The index of the line declaring `segments[depth]` at [cursor]'s block
/// level, or -1. The scan stops when the indentation backs out of the
/// parent block.
int _findKeyLine(
  List<String> lines,
  List<String> segments,
  int depth,
  int cursor,
) {
  final indent = '  ' * depth;
  final tail = r':(\s.*)?$';
  final pattern = RegExp(
    '^${RegExp.escape(indent)}${RegExp.escape(segments[depth])}$tail',
  );
  for (var i = cursor; i < lines.length; i++) {
    if (_indentOf(lines[i]) < depth * 2 && i > cursor) break;
    if (pattern.hasMatch(lines[i])) return i;
  }
  return -1;
}

/// Whether a single [leafLines] entry may ride the `key: value` line.
/// A rendered block entry (a `- item` sequence line — dash SPACE, the
/// yaml sequence indicator — or a bare `-`) must go under a bare `key:`
/// line — gluing it inline produced invalid yaml for one-element
/// lists/maps. A negative number scalar (`-1`) is NOT an entry: the
/// plain `startsWith('-')` check corrupted every nested scalar upsert
/// with a negative value (issue #393 retry knobs).
bool _inlineSafeLine(String line) {
  final trimmed = line.trim();
  if (trimmed.startsWith('- ') || trimmed == '-') return false;
  // An indented line is a block map entry; flow-empties stay inline-safe.
  if (line != trimmed) return false;
  return true;
}

/// Inserts the missing `segments[depth..]` chain — at EOF for a new
/// top-level section, otherwise at the top of the parent's block — and
/// returns the joined text.
String _insertChain(
  List<String> lines,
  List<String> segments,
  int depth,
  int cursor,
  List<String> leafLines,
  bool hadTrailingNewline,
) {
  final insertAt = depth == 0 ? lines.length : cursor;
  if (depth == 0 && lines.isNotEmpty && lines.last.trim().isNotEmpty) {
    lines.add('');
  }
  var at = insertAt;
  for (var d = depth; d < segments.length; d++) {
    final isLeaf = d == segments.length - 1;
    if (isLeaf && leafLines.length == 1 && _inlineSafeLine(leafLines[0])) {
      lines.insert(at, '${'  ' * d}${segments[d]}: ${leafLines[0]}');
      break;
    }
    lines.insert(at++, '${'  ' * d}${segments[d]}:');
    if (isLeaf) {
      for (final line in leafLines) {
        lines.insert(at++, line);
      }
    }
  }
  return _join(lines, hadTrailingNewline);
}

/// Swaps the leaf key line at [found] for [leafLines]: a single line keeps
/// the key's trailing comment inline, a block replaces the key's old body
/// (scalar or nested block) up to the parent's dedent.
String _replaceLeaf(
  List<String> lines,
  String key,
  int depth,
  int found,
  List<String> leafLines,
  bool hadTrailingNewline,
) {
  final indent = '  ' * depth;
  final comment = _trailingComment(lines[found]);
