  factory ModelCapabilityOverrides.fromYaml(Object? node) {
    if (node == null) return ModelCapabilityOverrides();
    if (node is! YamlMap) {
      throw ConfigException('models.overrides must be a map, got: $node');
    }
    final overrides = ModelCapability…

