          : '${current.contextWindow} tokens',
    ),
    (
      'maxTokens',
      'Max output tokens',
      current.maxTokens == null
          ? 'not pinned (catalog default)'
          : '${current.maxTokens} tokens',
    ),
    (
      'thinkingLevel',
      'Thinking level',
      current.thinkingLevel == null
