/// historical `.fah/memory` layout.
final MemoryConfig? memoryConfig;

/// The resolved `spills:` section (issue #678) — project yaml wins over
/// the user one, wholesale. Null or inactive (`enabled: false` /
/// `threshold: 0`) = no spill hooks attached, byte-identical legacy.
final SpillsConfig? spills;

/// The live models config (the `models:` section of `~/.fah/config.yaml`),
/// shared with the executable: `/models set`/`/models remove` mutate its
/// media slot overrides and `/model <name>` resolves its custom model
/// definitions; the host persists it after [onModelsConfigChanged]. Null
/// (web, tests without one) disables the models-config commands.
final ModelsConfig? modelsConfig;

/// Called when the models config changes (`/models set`,
/// `/models remove`) so the executable can persist it.
final void Function()? onModelsConfigChanged;

/// Called when the user switches the active model via `/model`.
///
  if (parts.length < 2 || parts.length > 3) {
    io.writeln('usage: /models set <slot> <model> [baseUrl]');
    return;
  }
  final slot = parts[0];
  if (!mediaModelSlotIds.contains(slot)) {
    io.writeln(
      'unknown slot: $slot (slots: ${mediaModelSlotIds.join(', ')})',
    );
    return;
  }
  final models = config.modelsConfig;
  if (models == null) {
    io.writeln('models config is unavailable on this host');
    return;
  }
  final baseUrl = parts.length == 3 ? parts[2] : _agent.state.model.baseUrl;
  models.setSlotOverride(
    slot,
    MediaSlotModelConfig(
      providerKind: 'openai-completions',
      baseUrl: baseUrl,
      modelId: parts[1],
    ),
  );
  io.writeln('slot $slot → ${parts[1]} @ $baseUrl (openai-completions)');
  config.onModelsConfigChanged?.call();
}

/// `/models remove <slot>`: drops a media slot override, returning the
/// slot to the main-connection fallback.
void _removeModelsSlot(String slot) {
  if (slot.isEmpty) {
    io.writeln('usage: /models remove <slot>');
    return;
  }
  if (!mediaModelSlotIds.contains(slot)) {
    io.writeln(
      'unknown slot: $slot (slots: ${mediaModelSlotIds.join(', ')})',
    );
    return;
  }
  final models = config.modelsConfig;
  if (models == null) {
    io.writeln('models config is unavailable on this host');
    return;
  }
  if (!models.removeSlotOverride(slot)) {
    io.writeln('no override for slot $slot');
    return;
  }
  io.writeln('slot $slot → main connection');
  config.onModelsConfigChanged?.call();
}

