    });
  });

  group('ModelsConfig overrides section', () {
    test('parses overrides alongside slots/custom', () {
      final models = ModelsConfig.fromYaml(_yaml('''
overrides:
  zai:
    glm-5.3-flash:
      maxTokens: 65536
      thinkingLevel: high
  openrouter:
    vendor/big-model:
      contextWindow: 1000000
'''));
      expect(models.overrides.length, 2);
