      models.removeOverride('zai', 'glm-5.3-flash');
      expect(models.overrides.lookup('zai', 'glm-5.3-flash'), isNull);
    });

    test('toYaml round-trips the overrides section', () {
      final models = ModelsConfig();
      models.setOverride(
        'zai',
        'glm-5.3-flash',
