      expect(caps.thinkingLevel, 'high');
      expect(caps.notes, isEmpty);
    });

    test('the gate never fires without a pin', () {
      final caps = _resolve(reasoning: false);
      expect(caps.thinkingLevel, isNull);
      expect(caps.notes, isEmpty);
    });
  });

