      final caps = _resolve(contextWindowCap: 100000);
      expect(caps.contextWindow, 100000);
    });

    test('cap raises to served truth', () {
      final caps = _resolve(contextWindowCap: 900000);
      expect(caps.contextWindow, 900000);
    });

