    test('a pin on a reasoning:false model is gated with a loud note', () {
      final caps = _resolve(
        override: const ModelCapabilityOverride(thinkingLevel: 'high'),
        reasoning: false,
      );
      expect(caps.thinkingLevel, isNull);
