  bool reasoning = true,
  OpenAICompletionsCompat? compat,
}) => Model(
  id: 'glm-5.3-flash',
  api: 'openai-completions',
  provider: 'zai',
  baseUrl: 'https://api.z.ai/api/coding/paas/v4',
  reasoning: reasoning,
