    // The caps menu re-renders with the pinned value shown in the row.
    await waitForIt(
      () => io.out.toString().contains('Max output tokens — 65536 tokens'),
    );
    io.sendLine('3'); // thinking level
    await waitForIt(
      () => io.out.toString().contains('thinking level'),
