    StreamFunction streamFunction, {
    ModelsConfig? modelsConfig,
    ModelRolesResolver? modelRolesResolver,
    String? homeDir,
    Future<List<String>> Function(String baseUrl, {required String apiKey})?
    modelsFetcher,
