      expect(override.isEmpty, isTrue);
    });

    test('xhigh/max thinking levels fold to high', () {
      final override = ModelCapabilityOverride.fromYaml(
        'zai',
        'glm-5.3-flash',
        _yaml('thinkingLevel: max'),
