      expect(override.thinkingLevel, 'high');
    });

    test('rejects unknown fields naming the key', () {
      expect(
        () => ModelCapabilityOverride.fromYaml('zai', 'glm-5.3-flash', _yaml('''
contextWindow: 200000
bogus: 1
''')),
        throwsA(
