  if (rolesResolver != null) {
    rolesResolver.setDefaultChain([
      ModelRef(
        provider: spec.name,
        modelId: def.model,
        baseUrl: def.baseUrl,
        contextWindow: def.contextWindow,
        maxTokens: def.maxTokens,
        input: def.input,
